{
    var errors = GradeRequestValidator.Validate(request);          // 400
    if (errors.Count > 0) return Results.ValidationProblem(errors);

    var state = await db.ReviewStates                                // 404, not 403
        .SingleOrDefaultAsync(x => x.Id == id && x.UserId == user.RequireUserId(), ct);
    if (state is null) return Results.NotFound();

    // ... grade it
